{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0004",
          "reason": "Indirect adviser statement; keep as context, not proof of Khamenei's own nuclear decision."
        },
        {
          "evidence_id": "E0005",
          "reason": "Institutional IAEA-side commitment under the system, but not a direct personal action by Khamenei."
        },
        {
          "evidence_id": "E0010",
          "reason": "External IAEA Board rebuke; useful pressure context, not evidence of Khamenei conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 Persian-language Khamenei transcript or decree on nuclear risk and safeguards",
          "lenses": ["1B.2", "1B.4", "1B.7", "1B.8"],
          "best_source_or_query_direction": "leader.ir archive, IRIB, official speech transcripts, IAEA correspondence",
          "why_it_matters": "Would separate Khamenei's own choices from adviser or institutional actions."
        },
        {
          "gap": "Cleaner evidence on expert appointments and command-chain choices in the nuclear file",
          "lenses": ["1B.3", "1B.6", "1B.7"],
          "best_source_or_query_direction": "official appointment announcements, IRGC/AEOI personnel records, serious reporting on nuclear advisers",
          "why_it_matters": "Would tighten attribution for risk-reducing or risk-increasing governance."
        }
      ],
      "reason": "Strong on 2022 deterioration in safeguards and monitoring, with some restraint rhetoric preserved, but several retained items are indirect or institutional rather than direct Khamenei orders. The package is usable, yet 1B.6-1B.8 remain underdeveloped."
    },
    {
      "chapter_id": "2B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0013",
          "reason": "Anonymous-sourced reconstruction of motive; keep as context, not as decisive proof of intent."
        },
        {
          "evidence_id": "E0018",
          "reason": "Sanctions against listed people/entities show Iranian-linked conduct, but not a direct Khamenei order."
        }
      ],
      "material_gaps": [
        {
          "gap": "Primary command-chain evidence for the March, September, and November Iraq strikes and drone support to Russia",
          "lenses": ["2B.2", "2B.5", "2B.9"],
          "best_source_or_query_direction": "IRGC statements, leaked orders, UN/security or judicial records, declassified intelligence",
          "why_it_matters": "Would distinguish direct ruler authorization from broader apparatus behavior."
        },
        {
          "gap": "Independent evidence of restraint or credible peace efforts in 2022",
          "lenses": ["2B.1", "2B.7"],
          "best_source_or_query_direction": "Iraq/Iran diplomatic records, UN mediation notes, ceasefire or CBM reporting",
          "why_it_matters": "Would test whether the aggressive record had meaningful counterweight."
        }
      ],
      "reason": "Fair on repeated cross-border coercion, proxy support, and civilian harm, but the most damaging items are often indirect or sanctions-based rather than direct command evidence. The negative case is strong, yet chain-of-command attribution and defensive-necessity rebuttal would be cleaner with primary Iranian texts or legal findings."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0032",
          "reason": "Morality-police shutdown was unconfirmed in the article itself; keep only as weak context."
        }
      ],
      "material_gaps": [],
      "reason": "Strong and fair. The dossier cleanly separates direct Khamenei incitement, security-force violence, and broader 2022 repression, while preserving contrary evidence. The only notable caveat is that some items are advocacy or post-period synthesis, but they are corroborated and do not distort the record."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package clearly shows protest-era censorship, arrests, and institutionalized suppression in 2022, with enough structural baseline to present the chapter fairly. The evidence is mostly system-level, which is appropriate here, and the absence of an election year does not create a gap."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0047",
          "reason": "Reported assessment of clerical leadership thinking; not a direct Khamenei policy document."
        },
        {
          "evidence_id": "E0048",
          "reason": "Raisi budget approval is indirect attribution to Khamenei rather than a ruler-specific economic act."
        },
        {
          "evidence_id": "E0049",
          "reason": "Cabinet appointment and macro context are regime-level, not Khamenei-specific implementation evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct Khamenei-linked economic implementation or appointments",
          "lenses": ["5B.2", "5B.7", "5B.9"],
          "best_source_or_query_direction": "official appointment and decree records, budget execution docs, Central Bank or IRNA policy announcements",
          "why_it_matters": "Would separate general regime economics from ruler-specific competence."
        },
        {
          "gap": "Household- and distribution-level 2022 welfare outcomes",
          "lenses": ["5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "household surveys, poverty, inflation, regional inequality and food-security data",
          "why_it_matters": "Would show whether policies improved ordinary people's conditions rather than only macro headlines."
        }
      ],
      "reason": "Mixed but usable. It captures 2022 macro strain, subsidy shock, and security-first budgeting, yet much of the material is speeches, broad macro context, or Raisi/cabinet-level actions rather than direct Khamenei economic execution. The package needs tighter ruler-specific implementation evidence."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0050",
          "reason": "WHO country story is structural pandemic context, not ruler-specific 2022 social policy."
        },
        {
          "evidence_id": "E0051",
          "reason": "Immunization survey describes system baseline and prior-year coverage, not direct Khamenei action."
        },
        {
          "evidence_id": "E0061",
          "reason": "UNICEF dashboard is country-level context, not ruler conduct."
        },
        {
          "evidence_id": "E0062",
          "reason": "WHO country data page is baseline context, not personal policy evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct Khamenei-linked social-policy decisions or corrective interventions in 2022",
          "lenses": ["6B.1", "6B.4", "6B.5", "6B.9"],
          "best_source_or_query_direction": "leader speeches, decrees, ministry appointment records, budget execution, cabinet minutes if available",
          "why_it_matters": "Would convert system-level service coverage into ruler-attributed action."
        },
        {
          "gap": "Independent household/service-quality evidence on who benefited",
          "lenses": ["6B.2", "6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "household surveys, equity breakdowns, education/health quality audits, refugee access studies",
          "why_it_matters": "Would test whether the welfare floor translated into equitable, durable gains."
        }
      ],
      "reason": "Fair on baseline welfare and service coverage, but the center of gravity is UNICEF and WHO system context rather than Khamenei-specific action. The dossier does not yet show direct ruler-linked welfare choices in 2022 or strong household-level attribution."
    },
    {
      "chapter_id": "7B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0071",
          "reason": "Treasury sanctions identify security officials and censorship, but not Khamenei's personal honesty or self-dealing."
        },
        {
          "evidence_id": "E0072",
          "reason": "U.S. policy statement about internet cutoff is regime-level concealment evidence, not direct personal integrity evidence."
        },
        {
          "evidence_id": "E0073",
          "reason": "Platform restriction is an implementation fact, not a personal truthfulness or conflict-of-interest record."
        },
        {
          "evidence_id": "E0074",
          "reason": "2013 Reuters Setad investigation is background context only and not 2022 conduct."
        },
        {
          "evidence_id": "E0075",
          "reason": "2015 Reuters Setad report is background context only and lacks direct evidence of 2022 personal enrichment."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 personal-integrity evidence beyond speeches and repression",
          "lenses": ["7B.3", "7B.4", "7B.5", "7B.6", "7B.7"],
          "best_source_or_query_direction": "asset and conflict-of-interest reporting, official filings, procurement records, investigative reporting on office-linked entities",
          "why_it_matters": "Would show whether there was personal or family benefit, not just state control."
        },
        {
          "gap": "Direct evidence of correction, admission of error, or truthful accountability",
          "lenses": ["7B.1", "7B.2", "7B.8"],
          "best_source_or_query_direction": "official transcripts, interviews, internal letters, public corrections, court or audit findings",
          "why_it_matters": "Would separate rhetorical blame-shifting from a substantiated pattern of dishonesty."
        }
      ],
      "reason": "Not enough direct personal-integrity evidence. The dossier is strong on public blame-shifting and regime censorship, but much of the retained material is structural or older Setad background rather than 2022 personal gain, conflicts, or corrective honesty. This is a real gap for 7B, not just a minor caveat."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "Strong enough to present a competence story: explicit program language, budget priorities, appointments, sanctions-evasion, and end-of-year trajectory are all covered, while moral judgments are kept separate. Remaining weaknesses are mostly attribution granularity and some post-period or sanctions-mediated corroboration, not a missing core narrative."
    }
  ]
}
